#!/bin/sh
# usage: seo.sh
# Uploads the files that make https://filetrace.eorlov.org discoverable to
# crawlers and language models to the R2 bucket the Worker serves them from:
#
#   robots.txt, sitemap.xml, llms.txt, llms-full.txt  generated by the docs site
#   ai.txt, security.txt, .well-known/security.txt, humans.txt  kept beside this
#
# The Worker also keeps a copy of the generated files in R2 and refreshes one
# that has gone stale, so running this seeds them and forces a refresh. It needs
# a Wrangler login or CLOUDFLARE_API_TOKEN. R2_BUCKET_NAME names the bucket;
# FILETRACE_DOCS_HOST overrides the docs host the generated files are read from.
set -eu

root=$(CDPATH='' cd -- "$(dirname -- "$0")/../.." && pwd)
: "${R2_BUCKET_NAME:?names the bucket of the download site}"
docs=${FILETRACE_DOCS_HOST:-filetrace.mintlify.site}
wrangler=${WRANGLER:-"npx --yes wrangler@4"}

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# A large object can fail on a transient fetch; retry a few times.
put()
{
    n=1
    while :; do
        if $wrangler r2 object put "$R2_BUCKET_NAME/$1" --file="$2" \
            --content-type="$3" --remote >/dev/null 2>&1; then
            printf 'uploaded %s\n' "$1"
            return 0
        fi
        [ "$n" -ge 3 ] && {
            printf 'could not upload %s\n' "$1" >&2
            return 1
        }
        n=$((n + 1))
        sleep 3
    done
}

# The generated files name Mintlify hosts; the Worker rewrites them to the
# public domain, and so does this.
for name in robots.txt sitemap.xml llms.txt llms-full.txt; do
    case $name in
    *.xml) type='application/xml; charset=utf-8' ;;
    *) type='text/plain; charset=utf-8' ;;
    esac
    curl -fsS "https://$docs/$name" |
        sed -E 's#https://filetrace\.mintlify\.(app|site)#https://filetrace.eorlov.org#g' >"$work/$name"
    put "$name" "$work/$name" "$type"
done

seo="$root/packaging/site/seo"
put "ai.txt" "$seo/ai.txt" 'text/plain; charset=utf-8'
put "security.txt" "$seo/security.txt" 'text/plain; charset=utf-8'
put ".well-known/security.txt" "$seo/security.txt" 'text/plain; charset=utf-8'
put "humans.txt" "$seo/humans.txt" 'text/plain; charset=utf-8'
